import { OutputChannel } from './OutputChannel';
import { EngineResults } from './EngineResults';
import type { OutputChannelConfig, Subscriber } from './interfaces';

export class ArtifactEngine {
  private channels: Map<string, OutputChannel> = new Map();

  registerOutputChannel(config: OutputChannelConfig): OutputChannel {
    if (this.channels.has(config.name)) {
      throw new Error(`Channel already exists: ${config.name}`);
    }
    const channel = new OutputChannel(config);
    this.channels.set(config.name, channel);
    return channel;
  }

  emit(channelName: string, artifact: unknown): void {
    const channel = this.channels.get(channelName);
    if (!channel) {
      throw new Error(`Unknown channel: ${channelName}`);
    }
    channel.emit(artifact);
  }

  getResults(): EngineResults {
    return new EngineResults(this.channels);
  }

  subscribe(channelName: string, callback: Subscriber): () => void {
    const channel = this.channels.get(channelName);
    if (!channel) {
      throw new Error(`Unknown channel: ${channelName}`);
    }
    return channel.subscribe(callback);
  }

  reset(): void {
    for (const channel of this.channels.values()) {
      channel.clear();
    }
  }

  getChannel(name: string): OutputChannel | undefined {
    return this.channels.get(name);
  }
}

