import { SetArtifact } from './SetArtifact';
import { MapArtifact } from './MapArtifact';
import { ValueArtifact } from './ValueArtifact';
import type {
  OutputChannelConfig,
  ArtifactType,
  KeyStrategy,
  MergeStrategy,
  Subscriber,
} from './interfaces';

export class OutputChannel {
  readonly name: string;
  readonly artifactType: ArtifactType;
  private keyStrategy: KeyStrategy;
  private mergeStrategy: MergeStrategy;
  private validator?: (artifact: unknown) => boolean;
  private transform?: (artifact: unknown) => unknown;
  private subscribers: Set<Subscriber> = new Set();

  private setArtifact?: SetArtifact<unknown>;
  private mapArtifact?: MapArtifact<unknown>;
  private valueArtifact?: ValueArtifact<unknown>;

  constructor(config: OutputChannelConfig) {
    this.name = config.name;
    this.artifactType = config.artifactType;
    this.keyStrategy = config.keyStrategy ?? 'replace';
    this.mergeStrategy = config.mergeStrategy ?? 'replace';
    this.validator = config.validator;
    this.transform = config.transform;

    this.initializeArtifact();
  }

  private initializeArtifact(): void {
    switch (this.artifactType) {
      case 'set':
        this.setArtifact = new SetArtifact<unknown>();
        break;
      case 'map':
        this.mapArtifact = new MapArtifact<unknown>(this.keyStrategy);
        break;
      case 'value':
        this.valueArtifact = new ValueArtifact<unknown>(this.mergeStrategy);
        break;
    }
  }

  emit(artifact: unknown): void {
    let processed = artifact;

    if (this.transform) {
      processed = this.transform(processed);
    }

    if (this.validator && !this.validator(processed)) {
      throw new Error(`Validation failed for channel: ${this.name}`);
    }

    switch (this.artifactType) {
      case 'set':
        this.emitToSet(processed);
        break;
      case 'map':
        this.emitToMap(processed);
        break;
      case 'value':
        this.emitToValue(processed);
        break;
    }

    this.notifySubscribers(processed);
  }

  private emitToSet(artifact: unknown): void {
    if (Array.isArray(artifact)) {
      this.setArtifact!.addMany(artifact);
    } else {
      this.setArtifact!.add(artifact);
    }
  }

  private emitToMap(artifact: unknown): void {
    if (typeof artifact !== 'object' || artifact === null) {
      throw new Error(`Map channel expects an object, got: ${typeof artifact}`);
    }
    const obj = artifact as Record<string, unknown>;
    for (const [key, value] of Object.entries(obj)) {
      this.mapArtifact!.set(key, value);
    }
  }

  private emitToValue(artifact: unknown): void {
    this.valueArtifact!.set(artifact);
  }

  private notifySubscribers(artifact: unknown): void {
    for (const subscriber of this.subscribers) {
      subscriber(artifact);
    }
  }

  subscribe(callback: Subscriber): () => void {
    this.subscribers.add(callback);
    return () => {
      this.subscribers.delete(callback);
    };
  }

  getArtifact(): SetArtifact<unknown> | MapArtifact<unknown> | ValueArtifact<unknown> {
    switch (this.artifactType) {
      case 'set':
        return this.setArtifact!;
      case 'map':
        return this.mapArtifact!;
      case 'value':
        return this.valueArtifact!;
    }
  }

  clear(): void {
    switch (this.artifactType) {
      case 'set':
        this.setArtifact!.clear();
        break;
      case 'map':
        this.mapArtifact!.clear();
        break;
      case 'value':
        this.valueArtifact!.clear();
        break;
    }
  }
}

