export class SetArtifact<T> {
  private data: Set<T> = new Set();

  add(value: T): void {
    this.data.add(value);
  }

  addMany(values: T[]): void {
    for (const value of values) {
      this.data.add(value);
    }
  }

  has(value: T): boolean {
    return this.data.has(value);
  }

  values(): T[] {
    return Array.from(this.data);
  }

  size(): number {
    return this.data.size;
  }

  merge(other: SetArtifact<T>): SetArtifact<T> {
    const result = new SetArtifact<T>();
    for (const value of this.data) {
      result.add(value);
    }
    for (const value of other.values()) {
      result.add(value);
    }
    return result;
  }

  clear(): void {
    this.data.clear();
  }
}

