import type { KeyStrategy } from './interfaces';

export class MapArtifact<V> {
  private data: Map<string, V> = new Map();
  private strategy: KeyStrategy;

  constructor(strategy: KeyStrategy = 'replace') {
    this.strategy = strategy;
  }

  set(key: string, value: V): void {
    if (this.data.has(key)) {
      switch (this.strategy) {
        case 'replace':
          this.data.set(key, value);
          break;
        case 'keep':
          // Do nothing, keep existing value
          break;
        case 'error':
          throw new Error(`Merge conflict for key: ${key}`);
      }
    } else {
      this.data.set(key, value);
    }
  }

  get(key: string): V | undefined {
    return this.data.get(key);
  }

  has(key: string): boolean {
    return this.data.has(key);
  }

  entries(): [string, V][] {
    return Array.from(this.data.entries());
  }

  keys(): string[] {
    return Array.from(this.data.keys());
  }

  values(): V[] {
    return Array.from(this.data.values());
  }

  size(): number {
    return this.data.size;
  }

  merge(other: MapArtifact<V>, strategy?: KeyStrategy): MapArtifact<V> {
    const mergeStrategy = strategy ?? this.strategy;
    const result = new MapArtifact<V>(mergeStrategy);

    for (const [key, value] of this.data) {
      result.data.set(key, value);
    }

    for (const [key, value] of other.entries()) {
      if (result.data.has(key)) {
        switch (mergeStrategy) {
          case 'replace':
            result.data.set(key, value);
            break;
          case 'keep':
            // Do nothing
            break;
          case 'error':
            throw new Error(`Merge conflict for key: ${key}`);
        }
      } else {
        result.data.set(key, value);
      }
    }

    return result;
  }

  clear(): void {
    this.data.clear();
  }
}

