import type { MergeStrategy } from './interfaces';
import { deepMerge } from './utils';

export class ValueArtifact<T> {
  private data: T | undefined;
  private strategy: MergeStrategy;

  constructor(strategy: MergeStrategy = 'replace') {
    this.strategy = strategy;
  }

  set(value: T): void {
    if (this.data === undefined) {
      this.data = value;
      return;
    }

    switch (this.strategy) {
      case 'replace':
        this.data = value;
        break;
      case 'keep':
        // Do nothing, keep existing value
        break;
      case 'append':
        this.data = this.appendValues(this.data, value);
        break;
      case 'error':
        throw new Error('Merge conflict: value already exists');
    }
  }

  private appendValues(existing: T, newValue: T): T {
    // String concatenation
    if (typeof existing === 'string' && typeof newValue === 'string') {
      return (existing + newValue) as T;
    }

    // Array concatenation
    if (Array.isArray(existing) && Array.isArray(newValue)) {
      return [...existing, ...newValue] as T;
    }

    // Object merging
    if (
      typeof existing === 'object' &&
      existing !== null &&
      typeof newValue === 'object' &&
      newValue !== null &&
      !Array.isArray(existing) &&
      !Array.isArray(newValue)
    ) {
      return deepMerge(existing as Record<string, unknown>, newValue as Record<string, unknown>) as T;
    }

    // For other types, just replace
    return newValue;
  }

  get(): T | undefined {
    return this.data;
  }

  hasValue(): boolean {
    return this.data !== undefined;
  }

  merge(other: ValueArtifact<T>, strategy?: MergeStrategy): ValueArtifact<T> {
    const mergeStrategy = strategy ?? this.strategy;
    const result = new ValueArtifact<T>(mergeStrategy);

    if (this.data !== undefined) {
      result.data = this.data;
    }

    if (other.data !== undefined) {
      if (result.data === undefined) {
        result.data = other.data;
      } else {
        switch (mergeStrategy) {
          case 'replace':
            result.data = other.data;
            break;
          case 'keep':
            // Do nothing
            break;
          case 'append':
            result.data = result.appendValues(result.data, other.data);
            break;
          case 'error':
            throw new Error('Merge conflict: both artifacts have values');
        }
      }
    }

    return result;
  }

  clear(): void {
    this.data = undefined;
  }
}

