import type { OutputChannel } from './OutputChannel';
import { SetArtifact } from './SetArtifact';
import { MapArtifact } from './MapArtifact';
import { ValueArtifact } from './ValueArtifact';

export class EngineResults {
  private channelMap: Map<string, OutputChannel>;

  constructor(channels: Map<string, OutputChannel>) {
    this.channelMap = channels;
  }

  get(channelName: string): unknown {
    const channel = this.channelMap.get(channelName);
    if (!channel) {
      return undefined;
    }

    const artifact = channel.getArtifact();

    if (artifact instanceof SetArtifact) {
      return artifact.values();
    }

    if (artifact instanceof MapArtifact) {
      return Object.fromEntries(artifact.entries());
    }

    if (artifact instanceof ValueArtifact) {
      return artifact.get();
    }

    return undefined;
  }

  channels(): string[] {
    return Array.from(this.channelMap.keys());
  }

  hasData(channelName: string): boolean {
    const channel = this.channelMap.get(channelName);
    if (!channel) {
      return false;
    }

    const artifact = channel.getArtifact();

    if (artifact instanceof SetArtifact) {
      return artifact.size() > 0;
    }

    if (artifact instanceof MapArtifact) {
      return artifact.size() > 0;
    }

    if (artifact instanceof ValueArtifact) {
      return artifact.hasValue();
    }

    return false;
  }

  getSet<T>(channelName: string): T[] {
    const channel = this.channelMap.get(channelName);
    if (!channel || channel.artifactType !== 'set') {
      return [];
    }
    return (channel.getArtifact() as SetArtifact<T>).values();
  }

  getMap<V>(channelName: string): Record<string, V> {
    const channel = this.channelMap.get(channelName);
    if (!channel || channel.artifactType !== 'map') {
      return {};
    }
    return Object.fromEntries((channel.getArtifact() as MapArtifact<V>).entries());
  }

  getValue<T>(channelName: string): T | undefined {
    const channel = this.channelMap.get(channelName);
    if (!channel || channel.artifactType !== 'value') {
      return undefined;
    }
    return (channel.getArtifact() as ValueArtifact<T>).get();
  }

  toJSON(): Record<string, unknown> {
    const result: Record<string, unknown> = {};
    for (const channelName of this.channels()) {
      result[channelName] = this.get(channelName);
    }
    return result;
  }
}

